urlset:
{%- for file in pages -%}
    {%- set page = file.page -%}
    {% if not page.is_link and (page.abs_url or page.canonical_url) and not (page.meta and page.meta.robots and "noindex" in page.meta.robots) %}

         {% if page.canonical_url %}{{ page.canonical_url|e }}{% else %}{{ page.abs_url|e }}{% endif %}
         {% if page.meta and page.meta.seo and page.meta.seo.modified %}{{ page.meta.seo.modified }}{% endif %}

    {%- endif -%}
{% endfor %}
